package edu.gcu.cst339.lab2_chinook_api.invoice;

import java.math.BigDecimal;
import java.time.LocalDateTime;

import jakarta.validation.constraints.DecimalMin;
import jakarta.validation.constraints.Digits;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;

/**
 * Data transfer object used as the JSON request and response body for invoices.
 *
 * <p>The validation annotations are checked when a request body is marked
 * {@code @Valid} in the controller.</p>
 *
 * @param invoiceId         the invoice ID; generated by the database, so it is
 *                          ignored on create and taken from the URL on update
 * @param customerId        ID of the customer who made the purchase; required and
 *                          must reference an existing customer
 * @param invoiceDate       date and time of the purchase; required
 * @param billingAddress    billing street address; optional, at most 70 characters
 * @param billingCity       billing city; optional, at most 40 characters
 * @param billingState      billing state or province; optional, at most 40 characters
 * @param billingCountry    billing country; optional, at most 40 characters
 * @param billingPostalCode billing postal code; optional, at most 10 characters
 * @param total             invoice total; required, zero or more, at most 8 digits
 *                          before the decimal point and 2 after
 */
public record InvoiceDto(
        Integer invoiceId,
        @NotNull
        Integer customerId,
        @NotNull
        LocalDateTime invoiceDate,
        @Size(max = 70)
        String billingAddress,
        @Size(max = 40)
        String billingCity,
        @Size(max = 40)
        String billingState,
        @Size(max = 40)
        String billingCountry,
        @Size(max = 10)
        String billingPostalCode,
        @NotNull
        @DecimalMin("0.00")
        @Digits(integer = 8, fraction = 2)
        BigDecimal total
) {
    /**
     * Converts an invoice entity into a DTO.
     *
     * @param invoice the entity to convert
     * @return a DTO containing all of the entity's fields
     */
    static InvoiceDto fromEntity(Invoice invoice) {
        return new InvoiceDto(
                invoice.getInvoiceId(),
                invoice.getCustomerId(),
                invoice.getInvoiceDate(),
                invoice.getBillingAddress(),
                invoice.getBillingCity(),
                invoice.getBillingState(),
                invoice.getBillingCountry(),
                invoice.getBillingPostalCode(),
                invoice.getTotal()
        );
    }
}